import { createTheme, Theme } from "@mui/material/styles";

import { getPalette, ThemeMode } from "./palette";
import typography from "./typography";
import { getComponents } from "./components";

/**
 * =====================================================
 * THEME FACTORY
 * =====================================================
 * Creates a full MUI theme for a given colour mode (light/dark).
 * Used by ThemeModeContext to re-theme the whole app on toggle.
 */
export const createAppTheme = (mode: ThemeMode): Theme =>
  createTheme({
    shape: {
      // Global default radius — every MUI surface inherits 12px so no card
      // can fall back to MUI's default (4px) or any other value.
      // Using 12 as number so it can be used in calculations
      borderRadius: 12,
    },
    palette: getPalette(mode),
    typography,
    components: getComponents(mode),
  });

const theme = createAppTheme("light");

export default theme;
